'use strict';
let dailyBusy=false;
function dailyArticlesHTML(editions){return editions.map(e=>`<section class="daily-edition"><h2>${esc(e.date)}</h2><div class="daily-grid">${e.articles.map(a=>`<article class="daily-article"><div class="daily-tickers">${a.tickers.map(t=>`<button data-ticker="${esc(t)}">${esc(t)}</button>`).join('')}<small>Source date ${esc(a.published)}</small></div><h3>${esc(a.title)}</h3><p class="daily-tldr">${esc(a.tldr)}</p><p><b>Why it matters</b> ${esc(a.why)}</p><p><b>Risk / uncertainty</b> ${esc(a.risk)}</p><p><b>Watch next</b> ${esc(a.watch)}</p><div class="daily-sources">${a.sources.map((u,i)=>researchLink(u,'Source '+(i+1))).join(' · ')}</div><small class="muted">Hermes / Grok · interpretation, not a verified trading signal</small></article>`).join('')}</div></section>`).join('')||'<p class="empty">No daily briefs published yet. Verified source links are required before an article can appear.</p>'}
async function loadDailyResearch(){if(dailyBusy)return;dailyBusy=true;try{const r=await getLiveJSON('/api/research/daily');$('#dailyArticles').innerHTML=dailyArticlesHTML(r.editions||[]);const overdue=r.lastAttempt&&Date.now()-Date.parse(r.lastAttempt)>36*3600000;$('#dailyStatus').textContent=(overdue?'Daily job overdue · ':'')+(r.status||'Daily research')+(r.lastAttempt?' · Checked '+stamp(r.lastAttempt):'')+' · '+r.schedule}catch{$('#dailyStatus').textContent='Daily research unavailable; retry shortly. Previously loaded briefs remain visible.'}finally{dailyBusy=false}}
if(typeof window!=='undefined'){$('#dailyRefresh').onclick=loadDailyResearch;setInterval(()=>{if(!document.hidden&&view==='daily')loadDailyResearch()},15*60000)}
